}

enum TriggerWhen: Codable, Hashable, Sendable {
    /// Once, at `at` in Unix milliseconds.
    case once(Once)
    case every(Every)
    /// Each day at `minute` past midnight on the host's clock, on `weekdays`
    /// counted from Sunday as 0, or on every day when there are none.
    case daily(Daily)
    /// On each request to `url`, the address senders post to.
    case webhook(Webhook)
    /// Once, when CI on `on` ends: a commit or a run, as the agent named it.
    case ci(Ci)
    /// One added after this build, by its `kind`.
    case unknown(String)

    struct Once: Codable, Hashable, Sendable {
        var at: Int
    }

    struct Every: Codable, Hashable, Sendable {
        var seconds: Int
    }

    struct Daily: Codable, Hashable, Sendable {
        var minute: Int
        var weekdays: [Int]
    }

    struct Webhook: Codable, Hashable, Sendable {
        var url: String
    }

    struct Ci: Codable, Hashable, Sendable {
        var on: String
    }

    private enum TagKey: String, CodingKey {
        case tag = "kind"
    }

    init(from decoder: any Decoder) throws {
        let tag = try decoder.container(keyedBy: TagKey.self).decode(String.self, forKey: .tag)
        switch tag {
        case "once":
            self = .once(try Once(from: decoder))
        case "every":
            self = .every(try Every(from: decoder))
        case "daily":
            self = .daily(try Daily(from: decoder))
        case "webhook":
            self = .webhook(try Webhook(from: decoder))
        case "ci":
            self = .ci(try Ci(from: decoder))
        default:
            self = .unknown(tag)
        }
    }

    func encode(to encoder: any Encoder) throws {
        let tag: String
        switch self {
        case .once(let value):
            try value.encode(to: encoder)
            tag = "once"
        case .every(let value):
            try value.encode(to: encoder)
            tag = "every"
        case .daily(let value):
            try value.encode(to: encoder)
            tag = "daily"
        case .webhook(let value):
            try value.encode(to: encoder)
            tag = "webhook"
        case .ci(let value):
            try value.encode(to: encoder)
            tag = "ci"
        case .unknown(let value):
            tag = value
        }
        var container = encoder.container(keyedBy: TagKey.self)
        try container.encode(tag, forKey: .tag)
    }
}

