        var turn: Int?
        /// The width the page was laid out at, in CSS pixels, for a screenshot
        /// the core took beside the agent's at a phone's or a tablet's width.
        var width: Int?
        /// The page the core opened itself to take it, once the check passed
        /// on a change to the project's pages; none for the agent's own.
        var opened: String?
    }

    struct Diff: Codable, Hashable, Sendable {
        var base: String
        var head: String
        /// The files it changes, the first few.
        var files: [String]
        var added: Int
        var removed: Int
    }

    struct Numbers: Codable, Hashable, Sendable {
        var measures: [Measure]
    }

    struct Run: Codable, Hashable, Sendable {
        var command: String
        /// The commit it ran on.
        var sha: String?
        /// The end of what it printed.
        var output: String
    }

    struct Timeline: Codable, Hashable, Sendable {
        var moments: [Moment]
    }

    private enum TagKey: String, CodingKey {
        case tag = "kind"
    }

    init(from decoder: any Decoder) throws {
        let tag = try decoder.container(keyedBy: TagKey.self).decode(String.self, forKey: .tag)
        switch tag {
        case "picture":
            self = .picture(try PicturePayload(from: decoder))
        case "diff":
            self = .diff(try Diff(from: decoder))
        case "numbers":
            self = .numbers(try Numbers(from: decoder))
        case "run":
            self = .run(try Run(from: decoder))
        case "timeline":
            self = .timeline(try Timeline(from: decoder))
        default:
            self = .unknown(tag)
        }
    }

    func encode(to encoder: any Encoder) throws {
        let tag: String
        switch self {
        case .picture(let value):
            try value.encode(to: encoder)
            tag = "picture"
        case .diff(let value):
            try value.encode(to: encoder)
            tag = "diff"
        case .numbers(let value):
            try value.encode(to: encoder)
            tag = "numbers"
        case .run(let value):
            try value.encode(to: encoder)
            tag = "run"
        case .timeline(let value):
            try value.encode(to: encoder)
            tag = "timeline"
        case .unknown(let value):
            tag = value
        }
        var container = encoder.container(keyedBy: TagKey.self)
        try container.encode(tag, forKey: .tag)
    }
}

