/// What a tab shows: one view, or several side by side.
enum Pane: Codable, Hashable, Sendable {
    case view(View)
    case split(Split)
    /// One added after this build, by its `type`.
    case unknown(String)

    struct View: Codable, Hashable, Sendable {
        var id: String
        var kind: PaneKind
        /// What it shows: an agent's id, a session's id, a path, a URL or a
        /// plugin's id, by `kind`.
        var target: String
    }

    struct Split: Codable, Hashable, Sendable {
        var id: String
        var dir: SplitDir
        var panes: [Pane]
        /// Each pane's share of the split, in thousandths.
        var sizes: [Int]
    }

    private enum TagKey: String, CodingKey {
        case tag = "type"
    }

    init(from decoder: any Decoder) throws {
        let tag = try decoder.container(keyedBy: TagKey.self).decode(String.self, forKey: .tag)
        switch tag {
        case "view":
            self = .view(try View(from: decoder))
        case "split":
            self = .split(try Split(from: decoder))
        default:
            self = .unknown(tag)
        }
    }

    func encode(to encoder: any Encoder) throws {
        let tag: String
        switch self {
        case .view(let value):
            try value.encode(to: encoder)
            tag = "view"
        case .split(let value):
            try value.encode(to: encoder)
            tag = "split"
        case .unknown(let value):
            tag = value
        }
        var container = encoder.container(keyedBy: TagKey.self)
        try container.encode(tag, forKey: .tag)
    }
}

