/// A way an agent says it can be signed in.
enum SignInMethod: Codable, Hashable, Sendable {
    /// Run the agent's own program again with `args` and `env`, in a terminal
    /// the person can see. A zero exit means it worked.
    case terminal(Terminal)
    /// Ask the agent to sign in by itself, through `authenticate`.
    case agent(Agent)
    /// One added after this build, by its `kind`.
    case unknown(String)

    struct Terminal: Codable, Hashable, Sendable {
        var id: String
        var name: String
        var description: String?
        var args: [String]
        var env: [WirePair<String, String>]
    }

    struct Agent: Codable, Hashable, Sendable {
        var id: String
        var name: String
        var description: String?
    }

    private enum TagKey: String, CodingKey {
        case tag = "kind"
    }

    init(from decoder: any Decoder) throws {
        let tag = try decoder.container(keyedBy: TagKey.self).decode(String.self, forKey: .tag)
        switch tag {
        case "terminal":
            self = .terminal(try Terminal(from: decoder))
        case "agent":
            self = .agent(try Agent(from: decoder))
        default:
            self = .unknown(tag)
        }
    }

    func encode(to encoder: any Encoder) throws {
        let tag: String
        switch self {
        case .terminal(let value):
            try value.encode(to: encoder)
            tag = "terminal"
        case .agent(let value):
            try value.encode(to: encoder)
            tag = "agent"
        case .unknown(let value):
            tag = value
        }
        var container = encoder.container(keyedBy: TagKey.self)
        try container.encode(tag, forKey: .tag)
    }
}

