    var reason: String
    var message: String?
}

/// What a chat is doing, which each client words.
enum ChatActivity: Codable, Hashable, Sendable {
    /// Going at a request again, as `Retrying` says.
    case retrying(RetryingPayload)
    /// Running the call this row draws.
    case call(Call)
    case thinking
    /// The agent's program is starting, with something sent to it.
    case starting
    /// Its session is being reached, with something sent to it.
    case connecting
    /// One added after this build, by its `kind`.
    case unknown(String)

    struct RetryingPayload: Codable, Hashable, Sendable {
        var attempt: Int?
        var connection: Bool
        /// What went wrong, in the agent's words.
        var reason: String?
    }

    struct Call: Codable, Hashable, Sendable {
        var row: ToolRow
    }

    private enum TagKey: String, CodingKey {
        case tag = "kind"
    }

    init(from decoder: any Decoder) throws {
        let tag = try decoder.container(keyedBy: TagKey.self).decode(String.self, forKey: .tag)
        switch tag {
        case "retrying":
            self = .retrying(try RetryingPayload(from: decoder))
        case "call":
            self = .call(try Call(from: decoder))
        case "thinking":
            self = .thinking
        case "starting":
            self = .starting
        case "connecting":
            self = .connecting
        default:
            self = .unknown(tag)
        }
    }

    func encode(to encoder: any Encoder) throws {
        let tag: String
        switch self {
        case .retrying(let value):
            try value.encode(to: encoder)
            tag = "retrying"
        case .call(let value):
            try value.encode(to: encoder)
            tag = "call"
        case .thinking:
            tag = "thinking"
        case .starting:
            tag = "starting"
        case .connecting:
            tag = "connecting"
        case .unknown(let value):
            tag = value
        }
        var container = encoder.container(keyedBy: TagKey.self)
        try container.encode(tag, forKey: .tag)
    }
}

/// The pages a turn of this chat changed, as the core took them once it finished.
