enum MdNode: Codable, Hashable, Sendable {
    case text(String)
    case element(MdElement)

    init(from decoder: any Decoder) throws {
        if let value = try? String(from: decoder) {
            self = .text(value)
            return
        }
        if let value = try? MdElement(from: decoder) {
            self = .element(value)
            return
        }
        throw DecodingError.dataCorrupted(.init(codingPath: decoder.codingPath, debugDescription: "MdNode matches no variant"))
    }

    func encode(to encoder: any Encoder) throws {
        switch self {
        case .text(let value):
            try value.encode(to: encoder)
        case .element(let value):
            try value.encode(to: encoder)
        }
    }
}

