/// One change to a chat a client holds. `in` names the subagent session whose
/// rows it changes; without it, the chat's own.
enum ChatChange: Codable, Hashable, Sendable {
    /// These fields of the head change; the rest stay. A delivery that catches a client up
    /// opens with one naming the number it follows, rather than one less than its own.
    case head(Head)
    /// A new row goes at the end, or a row already held is replaced whole.
    case row(Row)
    /// A new part goes at the end of the row, or a part already held is replaced.
    case part(Part)
    /// Text written on to the end of a text or thought part, and what that
    /// changes in its markdown tree.
    case text(Text)
    /// These fields of the row change; its parts stay.
    case set(Set)
    /// Only these rows stay, in this order: a client catching up drops the rest.
    case keep(Keep)
    /// The row and every row after it go.
    case drop(Drop)
    /// Everything held is replaced.
    case view(View)
    /// One added after this build, by its `op`.
    case unknown(String)

    struct Head: Codable, Hashable, Sendable {
        var set: JSONValue
        var follows: Int?
    }

    struct Row: Codable, Hashable, Sendable {
        var row: ChatMessage
        var `in`: String?
    }

    struct Part: Codable, Hashable, Sendable {
        var row: String
        var part: ChatPart
        var `in`: String?
    }

    struct Text: Codable, Hashable, Sendable {
        var row: String
        var part: String
        var text: String
        var md: MdChange?
        var `in`: String?
    }

    struct Set: Codable, Hashable, Sendable {
        var row: String
        var set: JSONValue
        var `in`: String?
    }

    struct Keep: Codable, Hashable, Sendable {
        var rows: [String]
    }

    struct Drop: Codable, Hashable, Sendable {
        var from: String
    }

    struct View: Codable, Hashable, Sendable {
        var view: ChatView
    }

    private enum TagKey: String, CodingKey {
        case tag = "op"
    }

    init(from decoder: any Decoder) throws {
        let tag = try decoder.container(keyedBy: TagKey.self).decode(String.self, forKey: .tag)
        switch tag {
        case "head":
            self = .head(try Head(from: decoder))
        case "row":
            self = .row(try Row(from: decoder))
        case "part":
            self = .part(try Part(from: decoder))
        case "text":
            self = .text(try Text(from: decoder))
        case "set":
            self = .set(try Set(from: decoder))
        case "keep":
            self = .keep(try Keep(from: decoder))
        case "drop":
            self = .drop(try Drop(from: decoder))
        case "view":
            self = .view(try View(from: decoder))
        default:
            self = .unknown(tag)
        }
    }

    func encode(to encoder: any Encoder) throws {
        let tag: String
        switch self {
        case .head(let value):
            try value.encode(to: encoder)
            tag = "head"
        case .row(let value):
            try value.encode(to: encoder)
            tag = "row"
        case .part(let value):
            try value.encode(to: encoder)
            tag = "part"
        case .text(let value):
            try value.encode(to: encoder)
            tag = "text"
        case .set(let value):
            try value.encode(to: encoder)
            tag = "set"
        case .keep(let value):
            try value.encode(to: encoder)
            tag = "keep"
        case .drop(let value):
            try value.encode(to: encoder)
            tag = "drop"
        case .view(let value):
            try value.encode(to: encoder)
            tag = "view"
        case .unknown(let value):
            tag = value
        }
        var container = encoder.container(keyedBy: TagKey.self)
        try container.encode(tag, forKey: .tag)
    }
}

/// What the core sends with a piece of an answer: the answer's length once it is added, and the
/// changes that bring the tree up to it.
struct MdChange: Codable, Hashable, Sendable {
    var n: Int
    var o: [MdOp]
}

/// One change to a tree a client holds. `p` is a path of indexes from the
/// top-level blocks down through each element's children (`c`, or a table's
/// `rows`, its cells and their contents). Positions in text count UTF-16
/// units, as clients slice it.
enum MdOp: Codable, Hashable, Sendable {
    /// The list at `p` keeps its first `at` entries and gains `c`.
    case list(List)
    /// The text at `p`, or a code block's `v` there, keeps its first `at` units and gains `s`.
    case text(Text)

    struct List: Codable, Hashable, Sendable {
        var p: [Int]
        var at: Int
        var c: [JSONValue]
    }

    struct Text: Codable, Hashable, Sendable {
        var p: [Int]
        var at: Int
        var s: String
    }

    init(from decoder: any Decoder) throws {
        if let value = try? List(from: decoder) {
            self = .list(value)
            return
        }
        if let value = try? Text(from: decoder) {
            self = .text(value)
            return
        }
        throw DecodingError.dataCorrupted(.init(codingPath: decoder.codingPath, debugDescription: "MdOp matches no variant"))
    }

    func encode(to encoder: any Encoder) throws {
        switch self {
        case .list(let value):
            try value.encode(to: encoder)
        case .text(let value):
            try value.encode(to: encoder)
        }
    }
}

