    var ticked: Tick?
}

/// Where a change is pinned on a piece of evidence.
enum Spot: Codable, Hashable, Sendable {
    /// A point on a picture, as fractions of its width and height from its top left; on a
    /// recording, in the frame `seconds` in.
    case point(Point)
    /// A moment of a recording, `seconds` in.
    case moment(MomentPayload)
    /// A line of a file in a diff, as the new side numbers it.
    case line(Line)
    /// One added after this build, by its `kind`.
    case unknown(String)

    struct Point: Codable, Hashable, Sendable {
        var x: Double
        var y: Double
        var seconds: Double?
    }

    struct MomentPayload: Codable, Hashable, Sendable {
        var seconds: Double
    }

    struct Line: Codable, Hashable, Sendable {
        var file: String
        var line: Int
    }

    private enum TagKey: String, CodingKey {
        case tag = "kind"
    }

    init(from decoder: any Decoder) throws {
        let tag = try decoder.container(keyedBy: TagKey.self).decode(String.self, forKey: .tag)
        switch tag {
        case "point":
            self = .point(try Point(from: decoder))
        case "moment":
            self = .moment(try MomentPayload(from: decoder))
        case "line":
            self = .line(try Line(from: decoder))
        default:
            self = .unknown(tag)
        }
    }

    func encode(to encoder: any Encoder) throws {
        let tag: String
        switch self {
        case .point(let value):
            try value.encode(to: encoder)
            tag = "point"
        case .moment(let value):
            try value.encode(to: encoder)
            tag = "moment"
        case .line(let value):
            try value.encode(to: encoder)
            tag = "line"
        case .unknown(let value):
            tag = value
        }
        var container = encoder.container(keyedBy: TagKey.self)
        try container.encode(tag, forKey: .tag)
    }
}

