        case tag = "type"
    }

    init(from decoder: any Decoder) throws {
        let tag = try decoder.container(keyedBy: TagKey.self).decode(String.self, forKey: .tag)
        switch tag {
        case "snapshot":
            self = .snapshot(try Snapshot(from: decoder))
        case "event":
            self = .event(try Event(from: decoder))
        default:
            self = .unknown(tag)
