/// What the core answers the window's `plugin` call with.
enum PluginOutcome: Codable, Hashable, Sendable {
    case value(JSONValue)
    case failed(PluginFailure)
    /// One added after this build, by its key.
    case unknown(String)

    init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: WireKey.self)
        guard let key = container.allKeys.first else {
            throw DecodingError.dataCorrupted(.init(codingPath: decoder.codingPath, debugDescription: "PluginOutcome names no variant"))
        }
        switch key.stringValue {
        case "value":
            self = .value(try container.decode(JSONValue.self, forKey: key))
        case "failed":
            self = .failed(try container.decode(PluginFailure.self, forKey: key))
        default:
            self = .unknown(key.stringValue)
        }
    }

    func encode(to encoder: any Encoder) throws {
        var container = encoder.container(keyedBy: WireKey.self)
        switch self {
        case .value(let value):
            try container.encode(value, forKey: WireKey("value"))
        case .failed(let value):
            try container.encode(value, forKey: WireKey("failed"))
        case .unknown(let key):
            try container.encode(JSONValue.null, forKey: WireKey(key))
        }
    }
}

/// How a plugin call failed, as the window shows it.
struct PluginFailure: Codable, Hashable, Sendable {
    var plugin: String
    var category: FailureCategory
    var message: String
    var status: Int?
}

/// What kind of failure a call met. Clients branch on it, so it stays stable
/// while the words in a failure's message may change.
enum FailureCategory: Codable, Hashable, Sendable {
    /// Not signed in.
    case unconfigured
    /// The service turned the sign-in down, so signing in again is what helps.
    case auth
    /// Signed in, but this account may not do that.
    case forbidden
    case rateLimited
    case http
    case badParams
    case notFound
    case unsupported
    /// The repository does not take that way of merging.
    case mergeMethod
    case keychain
    /// The service answered in a shape the plugin did not expect.
    case response
    case unknownMethod
    case streamClosed
    case `internal`
    case manifest
    case timedOut
    case notInstalled
    case disabled
    case stopped
    /// The service could not be reached at all.
    case offline
    /// The service was reached but did not answer in time.
    case timeout
    /// The core could not make sense of what it was asked or answered.
    case invalid
    /// A service's own error, named by the service.
    case own(String)

    init(rawValue: String) {
        switch rawValue {
        case "unconfigured": self = .unconfigured
        case "auth": self = .auth
        case "forbidden": self = .forbidden
        case "rate-limited": self = .rateLimited
        case "http": self = .http
        case "bad-params": self = .badParams
        case "not-found": self = .notFound
        case "unsupported": self = .unsupported
        case "merge-method": self = .mergeMethod
        case "keychain": self = .keychain
        case "response": self = .response
        case "unknown-method": self = .unknownMethod
        case "stream-closed": self = .streamClosed
        case "internal": self = .`internal`
        case "manifest": self = .manifest
        case "timed-out": self = .timedOut
        case "not-installed": self = .notInstalled
        case "disabled": self = .disabled
        case "stopped": self = .stopped
        case "offline": self = .offline
        case "timeout": self = .timeout
        case "invalid": self = .invalid
        default: self = .own(rawValue)
        }
    }

    var rawValue: String {
        switch self {
        case .unconfigured: return "unconfigured"
        case .auth: return "auth"
        case .forbidden: return "forbidden"
        case .rateLimited: return "rate-limited"
        case .http: return "http"
        case .badParams: return "bad-params"
        case .notFound: return "not-found"
        case .unsupported: return "unsupported"
        case .mergeMethod: return "merge-method"
        case .keychain: return "keychain"
        case .response: return "response"
        case .unknownMethod: return "unknown-method"
        case .streamClosed: return "stream-closed"
        case .`internal`: return "internal"
        case .manifest: return "manifest"
        case .timedOut: return "timed-out"
        case .notInstalled: return "not-installed"
        case .disabled: return "disabled"
        case .stopped: return "stopped"
        case .offline: return "offline"
        case .timeout: return "timeout"
        case .invalid: return "invalid"
        case .own(let value): return value
        }
    }

    init(from decoder: any Decoder) throws {
        self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
    }

    func encode(to encoder: any Encoder) throws {
        var container = encoder.singleValueContainer()
        try container.encode(rawValue)
    }
}

